require Storable;
require Storable;
require Storable;
require XML::NamespaceSupport;
require IO::Handle;
require XML::SAX;
require File::Basename;
require File::Spec;

# --- METRICS ---
# line_count: 11
# cyclomatic_complexity: 2
# max_nesting_depth: 2

# --- HINTS ---
# if/else: branches
# external_call: XML::Simple->new
# external_call: UNIVERSAL::isa
# method_chain: var: $self holds XML::Simple object
# method_chain: call: XML::Simple->new
# --- FUNCTION: _get_object ---
sub _get_object {
  my $self;
  if($_[0]  and  UNIVERSAL::isa($_[0], 'XML::Simple')) {
    $self = shift;
  }
  else {
    $self = XML::Simple->new();
  }

  return $self;
}

