## Specific Function to Test:
package XML::Simple;

# --- INCLUDES ---
use strict;
use warnings;
use warnings::register;
use Carp;
use Scalar::Util qw();
require Exporter;
use vars qw($VERSION @ISA @EXPORT @EXPORT_OK $PREFERRED_PARSER);
require File::Basename;
require XML::SAX;
require XML::Parser;
require Storable;
require Storable;
require Storable;
require XML::NamespaceSupport;
require IO::Handle;
require XML::SAX;
require File::Basename;
require File::Spec;

# --- METRICS ---
# line_count: 9
# cyclomatic_complexity: 1
# max_nesting_depth: 1

# --- HINTS ---
# method_chain: need: $self->handle_options
# method_chain: need: $self->build_simple_tree
# --- FUNCTION: parse_string ---
sub parse_string {
  my $self = &_get_object;      # note, @_ is passed implicitly

  my $string = shift;

  $self->handle_options('in', @_);

