# --- METRICS ---
# line_count: 182
# cyclomatic_complexity: 45
# max_nesting_depth: 8

# --- HINTS ---
# if/else: branches
# for/while: loop
# external_call: UNIVERSAL::isa
# method_chain: need: $self->{opt}
# method_chain: need: $self->new_hashref
# method_chain: need: $attr->{$key}
# method_chain: need: $self->normalise_space
# method_chain: need: $self->{_var_values}
# method_chain: need: $attr->{$k}
